def findPattern(board, pattern):
    R, C = len(board), len(board[0])
    r, c = len(pattern), len(pattern[0])

    for i in range(R - r + 1):
        for j in range(C - c + 1):
            letter_to_digit = {}
            digit_to_letter = {}
            ok = True
            for x in range(r):
                for y in range(c):
                    p_ch = pattern[x][y]
                    b_d = board[i + x][j + y]

                    if p_ch.isdigit():
                        if int(p_ch) != b_d:
                            ok = False
                            break
                    else:
                        if p_ch in letter_to_digit:
                            if letter_to_digit[p_ch] != b_d:
                                ok = False
                                break
                        else:
                            if b_d in digit_to_letter:
                                if digit_to_letter[b_d] != p_ch:
                                    ok = False
                                    break
                            letter_to_digit[p_ch] = b_d
                            digit_to_letter[b_d] = p_ch
                if not ok:
                    break
            if ok:
                return [i, j]
    return [-1, -1]
